You can use the built-in `unittest` module and the `unittest.mock` library for mocking. Here’s an example of how you can write a unit test suite for a user authentication module:

**User Class**
```python
class User:
    def __init__(self, username, password):
        self.username = username
        self.password = password

    def authenticate(self, password):
        return self.password == password

    def change_password(self, new_password):
        self.password = new_password
```

**Authentication Module**
```python
class Authenticator:
    def __init__(self):
        self.users = {}

    def register(self, username, password):
        self.users[username] = User(username, password)

    def login(self, username, password):
        user = self.users.get(username)
        return user and user.authenticate(password)

    def change_password(self, username, new_password):
        user = self.users.get(username)
        if user:
            user.change_password(new_password)
```

**Unit Tests**
```python
import unittest
from unittest.mock import patch
from user_auth import Authenticator
from user import User

class TestUser(unittest.TestCase):
    def test_init(self):
        user = User('john','secret')
        self.assertEqual(user.username, 'john')
        self.assertEqual(user.password,'secret')

    def test_authenticate(self):
        user = User('john','secret')
        self.assertTrue(user.authenticate('secret'))
        self.assertFalse(user.authenticate('wrong'))

    def test_change_password(self):
        user = User('john','secret')
        user.change_password('new_secret')
        self.assertEqual(user.password, 'new_secret')

class TestAuthenticator(unittest.TestCase):
    @patch('user_auth.Authenticator.users')
    def test_register(self, mock_users):
        authenticator = Authenticator()
        authenticator.register('john','secret')
        self.assertEqual(mock_users['john'].username, 'john')
        self.assertEqual(mock_users['john'].password,'secret')

    def test_login_valid(self):
        authenticator = Authenticator()
        authenticator.register('john','secret')
        self.assertTrue(authenticator.login('john','secret'))

    def test_login_invalid(self):
        authenticator = Authenticator()
        authenticator.register('john','secret')
        self.assertFalse(authenticator.login('john', 'wrong'))

    def test_login_nonexistent(self):
        authenticator = Authenticator()
        self.assertFalse(authenticator.login('nonexistent', 'wrong'))

    @patch('user_auth.Authenticator.users')
    def test_change_password(self, mock_users):
        authenticator = Authenticator()
        authenticator.change_password('john', 'new_secret')
        self.assertEqual(mock_users['john'].password, 'new_secret')

if __name__ == '__main__':
    unittest.main()
```

These tests cover the core functionality of the `User` and `Authenticator` classes, including registration, login, password change, and invalid input cases. You can run these tests using Python’s built-in `unittest` module.
